import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";
import shippingAPI from "../../services/shippingService";

export default function TrackShipment() {
  const navigate = useNavigate();
  const [awbNumber, setAwbNumber] = useState("");
  const [trackingData, setTrackingData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleTrack = async () => {
    if (!awbNumber.trim()) {
      setError("Please enter an AWB number");
      return;
    }

    setLoading(true);
    setError("");
    setTrackingData(null);

    try {
      const response = await shippingAPI.trackShipment(awbNumber.trim());

      if (response?.data?.status) {
        setTrackingData(response.data.data);
      } else {
        setError(
          response?.data?.message || "Failed to fetch tracking information"
        );
      }
    } catch (error) {
      console.error("Error tracking shipment:", error);
      setError(error.response?.data?.message || "Error tracking shipment");
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status) => {
    const statusColors = {
      Delivered: "text-green-600",
      "In Transit": "text-blue-600",
      "Out for Delivery": "text-orange-600",
      Pending: "text-yellow-600",
      Cancelled: "text-red-600",
      Returned: "text-red-600",
    };
    return statusColors[status] || "text-gray-600";
  };

  const formatDate = (dateString) => {
    if (!dateString) return "N/A";
    return new Date(dateString).toLocaleString();
  };

  const statusLabel = trackingData?.status
    ? trackingData.status.charAt(0).toUpperCase() +
      trackingData.status.slice(1)
    : "Unknown";

  return (
    <div className="track-shipment">
      <div className="track-shipment__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">Track Shipment</h3>
      </div>

      <div className="track-shipment__content">
        <div className="tracking-search">
          <div className="search-input-group">
            <input
              type="text"
              placeholder="Enter AWB Number"
              value={awbNumber}
              onChange={(e) => setAwbNumber(e.target.value)}
              className="search-input"
            />
            <button
              onClick={handleTrack}
              disabled={loading}
              className="button-red search-btn"
            >
              {loading ? "Tracking..." : "Track"}
            </button>
          </div>
          {error && <div className="error-message">{error}</div>}
        </div>

        {trackingData && (
          <div className="tracking-results">
            <div className="shipment-overview">
              <h4>Shipment Details</h4>
              <div className="overview-grid">
                <div className="overview-item">
                  <label>AWB Number:</label>
                  <span>{trackingData.awb_number || awbNumber}</span>
                </div>
                <div className="overview-item">
                  <label>Status:</label>
                  <span className={getStatusColor(statusLabel)}>
                    {statusLabel}
                  </span>
                </div>
                <div className="overview-item">
                  <label>Courier ID:</label>
                  <span>{trackingData.courier_id || "N/A"}</span>
                </div>
                <div className="overview-item">
                  <label>Order Number:</label>
                  <span>{trackingData.order_number || "N/A"}</span>
                </div>
                <div className="overview-item">
                  <label>Estimated Delivery:</label>
                  <span>{formatDate(trackingData.pdd)}</span>
                </div>
                <div className="overview-item">
                  <label>Created On:</label>
                  <span>{formatDate(trackingData.created)}</span>
                </div>
              </div>
            </div>

            {trackingData.history && trackingData.history.length > 0 && (
              <div className="tracking-events">
                <h4>Tracking History</h4>
                <div className="events-timeline">
                  {trackingData.history.map((event, index) => (
                    <div key={index} className="event-item">
                      <div className="event-dot"></div>
                      <div className="event-content">
                        <div className="event-status">{event.message}</div>
                        <div className="event-location">
                          {event.location || "N/A"}
                        </div>
                        <div className="event-date">
                          {formatDate(event.event_time)}
                        </div>
                        <div className="event-remark">
                          Status Code: {event.status_code}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="tracking-actions">
              <button
                className="btn btn-secondary"
                onClick={() => {
                  setTrackingData(null);
                  setAwbNumber("");
                  setError("");
                }}
              >
                Track Another
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
